#include <utility>

template <typename T>
class Box {
public:
    explicit Box(T value) : value_(std::move(value)) {}
    Box(Box&& other) noexcept : value_(std::move(other.value_)) {}
    const T& get() const { return value_; }

private:
    T value_;
};

int main() { return 0; }
